-- Überblick (22.10.2026, shared/model/overview.mjs): readReport legt mit dem Modell einen Überblick des Vorgangs in
-- payload.overview ab (Vorgang, Sitzungen, Unterlagen). Angezeigter Kurztext der Suchkarte (teaser): KI-Zusammenfassung, sonst
-- Auszug aus der Vorlage (ruleSummary), sonst Überblick, sonst der Text des Imports (shortSummary). Der Suchtext (search,
-- search_exact) nimmt den Überblick nicht auf: seine Wörter („Thema“, „Unterlagen“, „Gremium“) würden die Suche verfälschen.
-- Trigger sonst wie 0027; bestehende Karten ändern sich, wenn read-reports.mjs den Überblick schreibt.
DROP TRIGGER IF EXISTS `trg_search_cards_insert`;
--> statement-breakpoint
CREATE TRIGGER `trg_search_cards_insert` AFTER INSERT ON `topics` BEGIN
  INSERT INTO search_cards_gone (card_rowid,id,region_id,label,status,search) SELECT rowid,id,region_id,label,status,search FROM search_cards WHERE id=NEW.id;
  INSERT OR REPLACE INTO search_cards (id,region_id,date,status,label,title,teaser,gremium,search,search_exact)
  SELECT NEW.id, NEW.region_id, substr(NEW.event_date,1,10), NEW.status, coalesce((SELECT label FROM topic_effective_labels WHERE id=NEW.id),'unklar'), substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000), substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.overview.text')='text' THEN json_extract(NEW.payload,'$.overview.text') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200), coalesce(json_extract(NEW.payload,'$.committee'),''), lower(replace(replace(replace(replace(replace(replace(replace(substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000)||' '||substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200)||' '||coalesce(json_extract(NEW.payload,'$.committee'),''),'Ä','a'),'Ö','o'),'Ü','u'),'ä','a'),'ö','o'),'ü','u'),'ß','ss')), lower(replace(replace(replace(substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000)||' '||substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200)||' '||coalesce(json_extract(NEW.payload,'$.committee'),''),'Ä','ä'),'Ö','ö'),'Ü','ü')) WHERE json_extract(NEW.payload,'$.identity.mergedInto') IS NULL;
END;
--> statement-breakpoint
DROP TRIGGER IF EXISTS `trg_search_cards_update`;
--> statement-breakpoint
CREATE TRIGGER `trg_search_cards_update` AFTER UPDATE ON `topics`
  WHEN OLD.region_id IS NOT NEW.region_id
    OR OLD.event_date IS NOT NEW.event_date
    OR OLD.status IS NOT NEW.status
    OR json_extract(OLD.payload,'$.title') IS NOT json_extract(NEW.payload,'$.title')
    OR json_extract(OLD.payload,'$.shortSummary') IS NOT json_extract(NEW.payload,'$.shortSummary')
    OR json_extract(OLD.payload,'$.overview.text') IS NOT json_extract(NEW.payload,'$.overview.text')
    OR json_extract(OLD.payload,'$.generatedBy') IS NOT json_extract(NEW.payload,'$.generatedBy')
    OR json_extract(OLD.payload,'$.contentAnalysis.status') IS NOT json_extract(NEW.payload,'$.contentAnalysis.status')
    OR json_extract(OLD.payload,'$.ruleSummary.short.sentences') IS NOT json_extract(NEW.payload,'$.ruleSummary.short.sentences')
    OR json_extract(OLD.payload,'$.committee') IS NOT json_extract(NEW.payload,'$.committee')
    OR json_extract(OLD.payload,'$.officialTitle') IS NOT json_extract(NEW.payload,'$.officialTitle')
    OR json_extract(OLD.payload,'$.identity.mergedInto') IS NOT json_extract(NEW.payload,'$.identity.mergedInto')
    OR json_extract(OLD.payload,'$.classification.version') IS NOT json_extract(NEW.payload,'$.classification.version')
    OR json_extract(OLD.payload,'$.classification.method') IS NOT json_extract(NEW.payload,'$.classification.method')
    OR json_extract(OLD.payload,'$.classification.evidence') IS NOT json_extract(NEW.payload,'$.classification.evidence')
    OR json_extract(OLD.payload,'$.classification.primary') IS NOT json_extract(NEW.payload,'$.classification.primary')
    OR (SELECT label FROM search_cards WHERE id=OLD.id) IS NOT (SELECT label FROM topic_effective_labels WHERE id=NEW.id)
BEGIN
  INSERT INTO search_cards_gone (card_rowid,id,region_id,label,status,search) SELECT rowid,id,region_id,label,status,search FROM search_cards WHERE id=NEW.id OR id=OLD.id;
  DELETE FROM search_cards WHERE id=NEW.id OR id=OLD.id;
  INSERT OR REPLACE INTO search_cards (id,region_id,date,status,label,title,teaser,gremium,search,search_exact)
  SELECT NEW.id, NEW.region_id, substr(NEW.event_date,1,10), NEW.status, coalesce((SELECT label FROM topic_effective_labels WHERE id=NEW.id),'unklar'), substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000), substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.overview.text')='text' THEN json_extract(NEW.payload,'$.overview.text') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200), coalesce(json_extract(NEW.payload,'$.committee'),''), lower(replace(replace(replace(replace(replace(replace(replace(substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000)||' '||substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200)||' '||coalesce(json_extract(NEW.payload,'$.committee'),''),'Ä','a'),'Ö','o'),'Ü','u'),'ä','a'),'ö','o'),'ü','u'),'ß','ss')), lower(replace(replace(replace(substr(coalesce(json_extract(NEW.payload,'$.title'),''),1,1000)||' '||substr(CASE WHEN NOT (coalesce(json_extract(NEW.payload,'$.generatedBy'),'') LIKE 'KI-Zusammenfassung%' OR coalesce(json_extract(NEW.payload,'$.contentAnalysis.status'),'')='completed') AND json_type(NEW.payload,'$.ruleSummary.short.sentences')='array' THEN coalesce((SELECT group_concat(s.value,' ') FROM json_each(NEW.payload,'$.ruleSummary.short.sentences') s),'') ELSE coalesce(json_extract(NEW.payload,'$.shortSummary'),'') END,1,1200)||' '||coalesce(json_extract(NEW.payload,'$.committee'),''),'Ä','ä'),'Ö','ö'),'Ü','ü')) WHERE json_extract(NEW.payload,'$.identity.mergedInto') IS NULL;
END;
